private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int start = i;
    if (start >= bb.limit()) {
        return start;
    }
    int b1 = bb.get(start) & 0xFF;
    if (b1 < 0x80) {
        sb.append((char) b1);
        return start + 1;
    }
    int bytesNeeded;
    int codePoint;
    if ((b1 & 0xE0) == 0xC0) {
        bytesNeeded = 1;
        codePoint = b1 & 0x1F;
    } else if ((b1 & 0xF0) == 0xE0) {
        bytesNeeded = 2;
        codePoint = b1 & 0x0F;
    } else if ((b1 & 0xF8) == 0xF0) {
        bytesNeeded = 3;
        codePoint = b1 & 0x07;
    } else {
        sb.append('\uFFFD');
        return start + 1;
    }
    int end = start + 1 + bytesNeeded;
    if (end > bb.limit()) {
        sb.append('\uFFFD');
        return bb.limit();
    }
    for (int j = 0; j < bytesNeeded; j++) {
        int bj = bb.get(start + 1 + j) & 0xFF;
        if ((bj & 0xC0) != 0x80) {
            sb.append('\uFFFD');
            return start + 1 + j;
        }
        codePoint = (codePoint << 6) | (bj & 0x3F);
    }
    if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
    } else {
        codePoint -= 0x10000;
        char high = (char) ((codePoint >> 10) + 0xD800);
        char low = (char) ((codePoint & 0x3FF) + 0xDC00);
        sb.append(high).append(low);
    }
    return end;
}

