static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        return timeBucket;
    }
    int year = (int)(timeBucket / 10000);
    int month = (int)((timeBucket / 100) % 100);
    int day = (int)(timeBucket % 100);
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        return 0;
    }
    final int strLen = str.length();
    if (index < 0 || len < 0 || index + len > strLen) {
        throw new IllegalArgumentException("Invalid index or length for string length " + strLen);
    }

    int byteCount = 0;
    int pos = index;
    int end = index + len;

    try {
        while (pos < end) {
            char ch = str.charAt(pos);
            int codePoint = ch;

            // Handle surrogate pair
            if (Character.isHighSurrogate(ch) && pos + 1 < end) {
                char lo = str.charAt(pos + 1);
                if (Character.isLowSurrogate(lo)) {
                    codePoint = Character.toCodePoint(ch, lo);
                    pos++; // Consume low surrogate
                }
            }

            if (codePoint <= 0x7F) {
                byteCount += 1;
            } else if (codePoint <= 0x7FF) {
                byteCount += 2;
            } else if (codePoint <= 0xFFFF) {
                byteCount += 3;
            } else {
                byteCount += 4;
            }
            pos++;
        }
    } catch (IndexOutOfBoundsException | StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Index out of bounds while computing UTF-8 size", e);
    }

    return byteCount;
}

