public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate byteLength
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    // Validate byteOffset if array is not null
    if (byteArrayValue != null && (byteOffset < 0 || byteOffset > byteArrayValue.length)) {
        throw new IllegalArgumentException("byteOffset out of bounds");
    }
    // Ensure enough capacity
    int newLen = this.length + byteLength;
    if (newLen > this.data.length) {
        enlarge(byteLength);
    }
    // Copy bytes
    int dstPos = this.length;
    if (byteArrayValue == null) {
        // Insert nullbytes
        for (int i = 0; i < byteLength; i++) {
            this.data[dstPos++] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, this.data, dstPos, byteLength);
        dstPos += byteLength;
    }
    this.length = dstPos;
    return this;
}

