LinkedBuffer writeUTF8(CharSequence arg0, WriteSession arg1, LinkedBuffer arg2) {
    if (arg2 == null) {
        throw new IllegalArgumentException("LinkedBuffer must not be null");
    }
    if (arg0 == null || arg0.length() == 0) {
        return arg2;
    }
    int len = arg0.length();
    // Allocate a buffer large enough for worst case (4 bytes per char)
    byte[] temp = new byte[len * 4];
    int pos = 0;
    for (int i = 0; i < len; i++) {
        char ch = arg0.charAt(i);
        if (ch <= 0x7F) {
            temp[pos++] = (byte) ch;
        } else if (ch <= 0x7FF) {
            temp[pos++] = (byte) (0xC0 | (ch >> 6));
            temp[pos++] = (byte) (0x80 | (ch & 0x3F));
        } else {
            // Handle surrogate pairs
            if (Character.isHighSurrogate(ch) && i + 1 < len) {
                char low = arg0.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    int codePoint = Character.toCodePoint(ch, low);
                    temp[pos++] = (byte) (0xF0 | (codePoint >> 18));
                    temp[pos++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
                    temp[pos++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                    temp[pos++] = (byte) (0x80 | (codePoint & 0x3F));
                    i++; // Skip low surrogate
                    continue;
                }
            }
            temp[pos++] = (byte) (0xE0 | (ch >> 12));
            temp[pos++] = (byte) (0x80 | ((ch >> 6) & 0x3F));
            temp[pos++] = (byte) (0x80 | (ch & 0x3F));
        }
    }
    try {
        arg2.put(temp, 0, pos);
    } catch (Throwable t) {
        // In a real implementation, more sophisticated error handling would be used
        throw new RuntimeException("Failed to write UTF-8 bytes to LinkedBuffer", t);
    }
    return arg2;
}

