    boolean isAbsolute = path.startsWith("/");
    String[] parts = path.split("/");
    int startIndex = isAbsolute ? 1 : 0;
    for (int i = startIndex; i < parts.length; i++) {
        String segment = parts[i];
        if (decode) {
            try {
                segment = java.net.URLDecoder.decode(segment, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; rethrow as unchecked
                throw new RuntimeException(e);
            }
        }
        result.add(new PathSegmentImpl(segment));
    }
    return result;
}

