private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }
    int len = descriptor.length();
    int posIndex = 0; // index in the descriptor string
    boolean isMethod = len > 0 && descriptor.charAt(0) == '(';

    if (isMethod) {
        // skip the opening '('
        posIndex = 1;
        // parse argument types until ')'
        while (posIndex < len) {
            char c = descriptor.charAt(posIndex);
            if (c == ')') {
                // end of parameter list; nothing to pop for the return type
                break;
            }

            // pop one element from the stack
            if (--pos < 0) {
                throw new IllegalStateException("Attempt to pop from an empty frame stack");
            }

            // advance over the current type descriptor
            if (c == '[') {
                // skip all '[' characters
                while (posIndex < len && descriptor.charAt(posIndex) == '[') {
                    posIndex++;
                }
                // after array brackets, handle the element type
                if (posIndex < len && descriptor.charAt(posIndex) == 'L') {
                    // skip the class descriptor after '['s
                    posIndex = descriptor.indexOf(';', posIndex);
                    if (posIndex == -1) {
                        throw new IllegalArgumentException("Malformed descriptor: missing ';' after class name");
                    }
                    posIndex++; // move past ';'
                } else {
                    // primitive type after '['s
                    posIndex++;
                }
            } else if (c == 'L') {
                // skip class descriptor
                posIndex = descriptor.indexOf(';', posIndex);
                if (posIndex == -1) {
                    throw new IllegalArgumentException("Malformed descriptor: missing ';' after class name");
                }
                posIndex++; // move past ';'
            } else {
                // primitive type
                posIndex++;
            }
        }
    } else {
        // descriptor represents a single type
        if (--pos < 0) {
            throw new IllegalStateException("Attempt to pop from an empty frame stack");
        }

        char c = descriptor.charAt(posIndex);
        if (c == '[') {
            while (posIndex < len && descriptor.charAt(posIndex) == '[') {
                posIndex++;
            }
            if (posIndex < len && descriptor.charAt(posIndex) == 'L') {
                posIndex = descriptor.indexOf(';', posIndex);
                if (posIndex == -1) {
                    throw new IllegalArgumentException("Malformed descriptor: missing ';' after class name");
                }
                posIndex++;
            } else {
                posIndex++;
            }
        } else if (c == 'L') {
            posIndex = descriptor.indexOf(';', posIndex);
            if (posIndex == -1) {
                throw new IllegalArgumentException("Malformed descriptor: missing ';' after class name");
            }
        } else {
            // primitive type: single character
        }
    }
}

@Override public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("b");
    }
    if (off < 0 || len < 0 || off > b.length - len) {
        throw new IndexOutOfBoundsException();
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        byte[] newBuf = new byte[Math.max(buf.length << 1, newCount)];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

protected void addToIndex(V sourceVertex, V targetVertex, E e){
