    java.util.List<E> sourceList = edgeIndex.get(sourceVertex);
    if (sourceList == null) {
        sourceList = new java.util.ArrayList<>();
        edgeIndex.put(sourceVertex, sourceList);
    }
    sourceList.add(e);

    // Add edge to target vertex entry (for quick lookup from either side)
    java.util.List<E> targetList = edgeIndex.get(targetVertex);
