public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("Input box cannot be null");
    }
    double minX = box.getMinX();
    double minY = box.getMinY();
    double maxX = box.getMaxX();
    double maxY = box.getMaxY();
    double width = maxX - minX;
    double height = maxY - minY;
    if (width <= 0 || height <= 0) {
        throw new IllegalArgumentException("Box must have positive width and height");
    }
    double halfWidth = width / 2.0;
    double midX = minX + halfWidth;
    Box2D left  = new Box2D(minX, minY, halfWidth, height);
    Box2D right = new Box2D(midX, minY, halfWidth, height);
    return Pair.of(left, right);
}

