private void putAbstractTypes(final int start,final int end){
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame[i];
        int tag = type.getTag();
        stackMapTableEntries.writeByte((byte) tag);
        switch (tag) {
            case VerificationTypeInfo.ITEM_OBJECT:
            case VerificationTypeInfo.ITEM_UNINITIALIZED_OBJECT:
                // Write constant pool index
                int cpoolIndex = type.getCpoolOffset();
                stackMapTableEntries.writeUnsignedShort(cpoolIndex);
                break;
            case VerificationTypeInfo.ITEM_UNINITIALIZED:
                // Write offset of the new instruction
                int offset = type.getOffset();
                stackMapTableEntries.writeUnsignedShort(offset);
                break;
            // For other verification type tags (ITEM_Top, ITEM_Integer, ITEM_Float, ITEM_Double,
            // ITEM_Long, ITEM_Null, ITEM_UninitializedThis, ITEM_Dynamic, ITEM_InvokeDynamic,
            // ITEM_MethodHandle, ITEM_MethodType), no additional data is written.
            default:
                // No extra bytes needed for these tags
                break;
        }
    }
}

