@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type must not be null");
    }
    if (!Character.class.isAssignableFrom(type)) {
        throw new IllegalArgumentException("Target type is not Character");
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new Exception("String length > 1 cannot be converted to Character");
        }
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }
    throw new Exception("Cannot convert value to Character: " + value);
}

