            }
        }
    }
    return false;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    if (desiredCapacity <= 3) {
        return 3;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (candidate > 0 && candidate <= Integer.MAX_VALUE) {
        boolean isPrime = true;
        int sqrt = (int) Math.sqrt(candidate);
        if (candidate < 2) {
            isPrime = false;
        } else if (candidate % 2 == 0 && candidate != 2) {
            isPrime = false;
        } else {
            for (int i = 3; i <= sqrt; i += 2) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2; // only check odd numbers
    }
    return Integer.MAX_VALUE; // fallback if no prime found within int range
}

