@Override public String readString() throws IOException {
    // Read a 4-byte big-endian length prefix
    int length = 0;
    for (int i = 0; i < 4; i++) {
        int b = in.read();
        if (b == -1) {
            throw new EOFException("Unexpected end of stream while reading string length");
        }
        length = (length << 8) | (b & 0xFF);
    }
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }
    // Read the string bytes
    byte[] buffer = new byte[length];
    int offset = 0;
    while (offset < length) {
        int readCount = in.read(buffer, offset, length - offset);
        if (readCount == -1) {
            throw new EOFException("Unexpected end of stream while reading string data");
        }
        offset += readCount;
    }
    // Convert to String using UTF-8 encoding
    return new String(buffer, "UTF-8");
}

private static int digitValue(final char c){
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    }
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    }
    return -1;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < str.length()) {
            char next = str.charAt(i + 1);
            if (next == '\\') {
                sb.append('\\');
                i++;
                continue;
            }
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case 'u':
                    if (i + 5 >= str.length()) {
                        throw new Exception("Incomplete Unicode escape sequence");
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence: \\u" + hex);
                    }
                    i += 5; // Move past \\uXXXX
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int val = 0;
                        int count = 0;
                        while (j < str.length() && count < 3
                                && str.charAt(j) >= '0' && str.charAt(j) <= '7') {
                            val = val * 8 + (str.charAt(j) - '0');
                            j++;
                            count++;
                        }
                        sb.append((char) val);
                        i = j - 1;
                    } else {
                        // Unrecognized escape, keep literal char
                        sb.append(next);
                        i++;
                    }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

