private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null || set1.isEmpty() || set2.isEmpty()) {
        return new HashSet<>();
    }
    Set<V> result = new HashSet<>();
    if (set1.size() <= set2.size()) {
        for (V element : set1) {
            if (set2.contains(element)) {
                result.add(element);
            }
        }
    } else {
        for (V element : set2) {
            if (set1.contains(element)) {
                result.add(element);
            }
        }
    }
    return result;
}

