private JsonObject convertProperties(List<KeyStringValuePair> properties) {
    if (properties == null) {
        return null;
    }
    try {
        JsonObject jsonObject = new JsonObject();
        for (KeyStringValuePair pair : properties) {
            if (pair == null) {
                continue;
            }
            String key = pair.getKey();
            if (key == null) {
                continue;
            }
            Object valueObject = pair.getValue();
            if (valueObject == null) {
                continue;
            }
            if (valueObject instanceof String) {
                jsonObject.addProperty(key, (String) valueObject);
            } else if (valueObject instanceof Number) {
                jsonObject.addProperty(key, ((Number) valueObject).intValue());
            } else if (valueObject instanceof Boolean) {
                jsonObject.addProperty(key, (Boolean) valueObject);
            } else {
                // For any other Object types, store as string
                jsonObject.addProperty(key, valueObject.toString());
            }
