final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // the byte array holding the class file data
    byte[] classFileBuffer = this.classFileBuffer; // assumed field
    if (classFileBuffer == null) throw new IllegalStateException("classFileBuffer is not initialized");
    int offset = constantPoolEntryIndex;
    // Skip the tag byte
    if (offset < 0 || offset >= classFileBuffer.length) throw new IllegalArgumentException("Invalid entry index");
    offset++;
    if (offset + 1 >= classFileBuffer.length) throw new IllegalArgumentException("Truncated UTF8 entry");
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    offset += 2;
    if (offset + length > classFileBuffer.length) throw new IllegalArgumentException("UTF8 length extends beyond buffer");
    if (charBuffer == null || charBuffer.length < length * 2) {
        // UTF-8 can produce up to 2 chars per byte, use 4 to be safe
        throw new IllegalArgumentException("charBuffer too small for UTF8 string");
    }
    java.nio.ByteBuffer byteBuf = java.nio.ByteBuffer.wrap(classFileBuffer, offset, length);
    java.nio.charset.CharsetDecoder decoder = java.nio.charset.StandardCharsets.UTF_8.newDecoder();
    java.nio.CharBuffer outBuf = java.nio.CharBuffer.wrap(charBuffer, 0, charBuffer.length);
    decoder.decode(byteBuf, outBuf, true);
    outBuf.flip();
    return outBuf.toString();
}

