private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node must not be null");
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start);

    // If start already satisfies the predicate or is the stop, return immediately.
    if (start.equals(stop) || predicate.test(circ.current())) {
        return circ;
    }

    // Traverse until the stop node is reached or a node satisfying the predicate is found.
    while (true) {
        circ.next(dir);
        Node curNode = circ.current();
        if (curNode.equals(stop)) {
            return circ;
        }
        if (predicate.test(curNode)) {
            return circ;
        }
    }
}

