protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    try {
        if (tour == null || graph == null || tour.isEmpty()) {
            return null;
        }
        // Use a copy so we can remove edges as we traverse
        Set<E> remaining = new LinkedHashSet<>(tour);
        // Start with an arbitrary edge
        Iterator<E> it = remaining.iterator();
        E first = it.next();
        it.remove();
        // Determine order of vertices along the tour
        List<V> vertexList = new ArrayList<>();
        List<E> edgeList = new ArrayList<>();
        V curr = graph.getEdgeSource(first);
        V next = graph.getEdgeTarget(first);
        if (next.equals(curr)) { // handle potential self-loop
            next = graph.getEdgeSource(first);
        }
        vertexList.add(curr);
        vertexList.add(next);
        edgeList.add(first);
        curr = next;
        // Walk the rest of the edges
        while (!remaining.isEmpty()) {
            E chosen = null;
            for (E e : remaining) {
                V src = graph.getEdgeSource(e);
                V tgt = graph.getEdgeTarget(e);
                if (src.equals(curr) || tgt.equals(curr)) {
                    chosen = e;
                    break;
                }
            }
            if (chosen == null) {
                // No connecting edge found – invalid tour
                break;
            }
            remaining.remove(chosen);
            edgeList.add(chosen);
            V src = graph.getEdgeSource(chosen);
            V tgt = graph.getEdgeTarget(chosen);
            V newVertex = src.equals(curr) ? tgt : src;
            vertexList.add(newVertex);
            curr = newVertex;
        }
        // Ensure cycle closure
        if (!vertexList.get(0).equals(vertexList.get(vertexList.size() - 1))
                && !vertexList.isEmpty()) {
            vertexList.add(vertexList.get(0));
        }
        // Construct and return a GraphPath (assumes such a constructor exists)
        return new GraphPath<V, E>(vertexList, edgeList);
    } catch (Exception e) {
        return null;
    }
}

