    // Allocate a new slot for the constant pool entry.
    int idx = maxPoolSize;
    // Ensure the backing arrays can hold the new entry (implementation dependent).
    // This example assumes the arrays are large enough or will be resized elsewhere.

    // Store the entry in the constant pool.
    types[idx] = NAME_TYPE;      // constant pool tag for NameAndType
    offsets[idx]     = nameIdx;  // reference to the UTF‑8 name
    offsets[idx + 1] = descIdx; // reference to the UTF‑8 descriptor

    // Update the pool size to account for the two extra indices needed.
    maxPoolSize = idx + 2;
    return idx;
}

