    if (message == null) {
        return Filter.NEUTRAL;
    }
    // Return ACCEPT if the message contains a predefined pattern,
    // otherwise return NEUTRAL as specified.
    if (message.contains("MATCH_STRING")) {
        return Filter.ACCEPT;
    }
    return Filter.NEUTRAL;
}

