private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int count = 0;
    if (descriptor.charAt(0) == '('){
        int end = descriptor.indexOf(')');
        if (end < 0){
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
        String args = descriptor.substring(1, end);
        for (int i = 0; i < args.length();){
            char c = args.charAt(i);
            i++;
            if (c == 'L'){
                while (i < args.length() && args.charAt(i) != ';'){
                    i++;
                }
                if (i < args.length()){
                    i++; // skip ';'
                }
            } else if (c == '['){
                while (i < args.length() && args.charAt(i) == '['){
                    i++;
                }
                if (i < args.length()){
                    if (args.charAt(i) == 'L'){
                        i++;
                        while (i < args.length() && args.charAt(i) != ';'){
                            i++;
                        }
                        if (i < args.length()){
                            i++;
                        }
                    } else {
                        i++; // primitive component
                    }
                }
            } else {
                // primitive type, nothing else needed
            }
            count++;
        }
    } else {
        // single type descriptor; pop one slot
        count = 1;
    }
    while (count-- > 0 && pos > 0){
        pos--; // assume 'pos' tracks top of the output frame stack
    }
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys cannot be null");
    }
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            bounds.add(null);
        } else {
            int value;
            if (key instanceof Integer) {
                value = (Integer) key;
            } else if (key instanceof Number) {
                value = ((Number) key).intValue();
            } else {
                value = key.hashCode();
            }
            bounds.add(value);
        }
    }
    return bounds;
}

