public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non‑null");
    }
    try {
        java.nio.file.Path base = java.nio.file.Paths.get(path);
        java.nio.file.Path result = base.resolve(relativePath).normalize();
        return result.toString();
    } catch (Exception e) {
        // Fallback pathological handling
        if (relativePath.isEmpty() || relativePath.equals(".")) {
            return path;
        }
        // Basic manual resolution for "../" components
        java.util.List<String> baseParts = new java.util.ArrayList<>(java.util.Arrays.asList(path.split("/")));
        java.util.List<String> relParts = java.util.Arrays.asList(relativePath.split("/"));
        java.util.List<String> stack = new java.util.ArrayList<>();
        for (String part : baseParts) {
            if (!part.isEmpty()) stack.add(part);
        }
        for (String part : relParts) {
            if (part.equals("..")) {
                if (!stack.isEmpty()) stack.remove(stack.size() - 1);
            } else if (!part.equals(".") && !part.isEmpty()) {
                stack.add(part);
            }
        }
        StringBuilder sb = new StringBuilder();
        if (path.startsWith("/")) sb.append("/");
        for (int i = 0; i < stack.size(); i++) {
            if (i > 0) sb.append("/");
            sb.append(stack.get(i));
        }
        return sb.toString();
    }
}

